// Source text that `wp2payload init` writes into the user's project (spec 06, AC-A1/AC-A2).
// It should read like hand-written Payload 3 code: the user owns it after init and edits it freely.

const HEADER = '// Generated by wp2payload init. Edit freely.\n'

/** wp2payload.config.ts. URL and credentials are read from the environment, never written as literals. */
export function configTemplate(): string {
  return `import { defineConfig } from 'wp2payload'

// Generated by wp2payload init. Edit freely.
// Values come from the environment (.env or your shell): never put the password in this file.
export default defineConfig({
  source: {
    type: 'rest',
    url: process.env.WP_URL!,
    // A WordPress Application Password for a least-privilege user (Editor is enough).
    // Without it, only public content is read.
    auth: process.env.WP_APP_PASSWORD
      ? { user: process.env.WP_USER!, appPassword: process.env.WP_APP_PASSWORD }
      : undefined,
  },
  // WordPress type -> Payload collection slug (the blog preset). Point \`to\` at your own collections if you have them.
  collections: {
    post: { to: 'posts', fields: { content: 'content', excerpt: 'excerpt', featuredImage: 'heroImage' } },
    page: { to: 'pages', fields: { content: 'content', parent: 'parent' } },
    category: { to: 'categories' },
    post_tag: { to: 'tags' },
    media: { to: 'media' },
    author: { to: 'authors' },
  },
  // Old WordPress URLs keep working: @payloadcms/plugin-redirects when installed, else .wp2payload/redirects.json.
  redirects: { enabled: true },
})
`
}

export type ScaffoldFile =
  | 'wpMeta.ts'
  | 'access.ts'
  | 'blocks.ts'
  | 'editor.ts'
  | 'Posts.ts'
  | 'Pages.ts'
  | 'Categories.ts'
  | 'Tags.ts'
  | 'Authors.ts'
  | 'Media.ts'
  | 'index.ts'

const wpMeta = `${HEADER}import type { Field } from 'payload'

// Idempotency key wp2payload writes on every migrated document: re-runs update instead of duplicating.
// A copy of wp2payload's wpMetaField, so your production build does not depend on wp2payload.
export const wpMeta: Field = {
  name: 'wpMeta',
  type: 'group',
  admin: { readOnly: true, position: 'sidebar', description: 'Set by wp2payload. Do not edit.' },
  fields: [
    { name: 'site', type: 'text', index: true },
    { name: 'wpId', type: 'number', index: true },
    { name: 'link', type: 'text' },
    { name: 'sha256', type: 'text', index: true },
    { name: 'importedAt', type: 'date' },
  ],
}
`

const blocks = `${HEADER}import type { Block } from 'payload'

// Allow-listed iframes (YouTube, Vimeo...) become an embed block instead of raw HTML.
export const Embed: Block = {
  slug: 'embed',
  interfaceName: 'EmbedBlock',
  fields: [
    { name: 'url', type: 'text', required: true },
    { name: 'host', type: 'text', required: true },
  ],
}

// WordPress markup with no Lexical equivalent, kept sanitized so nothing is lost. Render it or rewrite it.
export const WpRawHtml: Block = {
  slug: 'wpRawHtml',
  interfaceName: 'WpRawHtmlBlock',
  fields: [{ name: 'html', type: 'code', required: true, admin: { language: 'html' } }],
}
`

const editor = `${HEADER}import { BlocksFeature, LinkFeature, lexicalEditor } from '@payloadcms/richtext-lexical'
import { Embed, WpRawHtml } from './blocks'

// Default Lexical features plus what migrated WordPress content needs: a \`rel\` on links
// (nofollow, sponsored...) and the embed and raw HTML blocks.
export const wpEditor = lexicalEditor({
  features: ({ defaultFeatures }) => [
    ...defaultFeatures.filter((feature) => feature.key !== 'link'),
    LinkFeature({
      fields: ({ defaultFields }) => [...defaultFields, { name: 'rel', type: 'text', label: 'Rel' }],
    }),
    BlocksFeature({ blocks: [Embed, WpRawHtml] }),
  ],
})
`

const access = `${HEADER}import type { Access } from 'payload'

// Public site content: anyone may read. Creating, updating and deleting stay at Payload's
// default, which is any logged-in user.
export const anyone: Access = () => true

// Visitors see published documents only; logged-in users also see drafts.
export const publishedOrLoggedIn: Access = ({ req }) => (req.user ? true : { _status: { equals: 'published' } })
`

const meta = `  {
      name: 'meta',
      type: 'group',
      label: 'SEO',
      fields: [
        { name: 'title', type: 'text' },
        { name: 'description', type: 'textarea' },
        { name: 'image', type: 'upload', relationTo: 'media' },
        { name: 'canonical', type: 'text', admin: { description: 'Absolute URL. Leave empty to use the page itself.' } },
        { name: 'noindex', type: 'checkbox', label: 'Hide from search engines' },
      ],
    },`

const slug = `{ name: 'slug', type: 'text', index: true, admin: { position: 'sidebar' } },`

const posts = `${HEADER}import type { CollectionConfig } from 'payload'
import { publishedOrLoggedIn } from './access'
import { wpEditor } from './editor'
import { wpMeta } from './wpMeta'

export const Posts: CollectionConfig = {
  slug: 'posts',
  access: { read: publishedOrLoggedIn },
  admin: { useAsTitle: 'title', defaultColumns: ['title', 'slug', 'publishedAt', '_status'] },
  versions: { drafts: true },
  fields: [
    { name: 'title', type: 'text', required: true },
    ${slug}
    { name: 'content', type: 'richText', editor: wpEditor },
    { name: 'excerpt', type: 'textarea' },
    { name: 'publishedAt', type: 'date', admin: { position: 'sidebar' } },
    { name: 'author', type: 'relationship', relationTo: 'authors', admin: { position: 'sidebar' } },
    { name: 'categories', type: 'relationship', relationTo: 'categories', hasMany: true, admin: { position: 'sidebar' } },
    { name: 'tags', type: 'relationship', relationTo: 'tags', hasMany: true, admin: { position: 'sidebar' } },
    { name: 'heroImage', type: 'upload', relationTo: 'media' },
  ${meta}
    wpMeta,
  ],
}
`

const pages = `${HEADER}import type { CollectionConfig } from 'payload'
import { publishedOrLoggedIn } from './access'
import { wpEditor } from './editor'
import { wpMeta } from './wpMeta'

export const Pages: CollectionConfig = {
  slug: 'pages',
  access: { read: publishedOrLoggedIn },
  admin: { useAsTitle: 'title', defaultColumns: ['title', 'slug', 'parent', '_status'] },
  versions: { drafts: true },
  fields: [
    { name: 'title', type: 'text', required: true },
    ${slug}
    { name: 'content', type: 'richText', editor: wpEditor },
    { name: 'publishedAt', type: 'date', admin: { position: 'sidebar' } },
    { name: 'author', type: 'relationship', relationTo: 'authors', admin: { position: 'sidebar' } },
    { name: 'parent', type: 'relationship', relationTo: 'pages', admin: { position: 'sidebar' } },
  ${meta}
    wpMeta,
  ],
}
`

const categories = `${HEADER}import type { CollectionConfig } from 'payload'
import { anyone } from './access'
import { wpMeta } from './wpMeta'

export const Categories: CollectionConfig = {
  slug: 'categories',
  access: { read: anyone },
  admin: { useAsTitle: 'name' },
  fields: [
    { name: 'name', type: 'text', required: true },
    ${slug}
    { name: 'description', type: 'textarea' },
    { name: 'parent', type: 'relationship', relationTo: 'categories', admin: { position: 'sidebar' } },
    wpMeta,
  ],
}
`

const tags = `${HEADER}import type { CollectionConfig } from 'payload'
import { anyone } from './access'
import { wpMeta } from './wpMeta'

export const Tags: CollectionConfig = {
  slug: 'tags',
  access: { read: anyone },
  admin: { useAsTitle: 'name' },
  fields: [
    { name: 'name', type: 'text', required: true },
    ${slug}
    wpMeta,
  ],
}
`

const authors = `${HEADER}import type { CollectionConfig } from 'payload'
import { anyone } from './access'
import { wpMeta } from './wpMeta'

// Public author profiles, not login accounts: WordPress users are never imported as Payload users.
export const Authors: CollectionConfig = {
  slug: 'authors',
  access: { read: anyone },
  admin: { useAsTitle: 'name' },
  fields: [
    { name: 'name', type: 'text', required: true },
    ${slug}
    wpMeta,
  ],
}
`

const media = `${HEADER}import type { CollectionConfig } from 'payload'
import { anyone } from './access'
import { wpMeta } from './wpMeta'

export const Media: CollectionConfig = {
  slug: 'media',
  access: { read: anyone },
  // A relative staticDir is resolved from the folder Payload runs in (process.cwd(), usually the
  // project root), not from this file. Use an absolute path, or a storage adapter for S3 and friends.
  upload: { staticDir: 'media' },
  fields: [
    { name: 'alt', type: 'text' },
    { name: 'caption', type: 'textarea' },
    wpMeta,
  ],
}
`

const index = `${HEADER}import type { CollectionConfig } from 'payload'
import { Authors } from './Authors'
import { Categories } from './Categories'
import { Media } from './Media'
import { Pages } from './Pages'
import { Posts } from './Posts'
import { Tags } from './Tags'

// Add to payload.config.ts: collections: [...wp2payloadCollections, /* your collections */]
export const wp2payloadCollections: CollectionConfig[] = [Posts, Pages, Categories, Tags, Authors, Media]

export { Authors, Categories, Media, Pages, Posts, Tags }
`

/** Files of the blog preset (doc 4.7), written in this order so `index.ts` lands last. */
export const SCAFFOLD_FILES: ReadonlyArray<readonly [ScaffoldFile, string]> = [
  ['wpMeta.ts', wpMeta],
  ['access.ts', access],
  ['blocks.ts', blocks],
  ['editor.ts', editor],
  ['Posts.ts', posts],
  ['Pages.ts', pages],
  ['Categories.ts', categories],
  ['Tags.ts', tags],
  ['Authors.ts', authors],
  ['Media.ts', media],
  ['index.ts', index],
]

/** Collection slugs the preset defines, with the file names a project usually keeps them in. */
export const PRESET_COLLECTIONS: ReadonlyArray<{ slug: string; kind: string; file: string }> = [
  { slug: 'posts', kind: 'post', file: 'Posts' },
  { slug: 'pages', kind: 'page', file: 'Pages' },
  { slug: 'categories', kind: 'category', file: 'Categories' },
  { slug: 'tags', kind: 'post_tag', file: 'Tags' },
  { slug: 'authors', kind: 'author', file: 'Authors' },
  { slug: 'media', kind: 'media', file: 'Media' },
]
